package com.sunmax.configure.controller;import com.alibaba.fastjson.JSON;import com.sunmax.common.dto.crontab.ComputeNodeListDto;import com.sunmax.common.dto.device.SiteDeviceTreeDto;import com.sunmax.common.dto.together.SystemDeviceListDto;import com.sunmax.common.util.ResponseResult;import com.sunmax.configure.dto.*;import com.sunmax.configure.service.DeviceFeignService;import com.sunmax.configure.service.GraphService;import com.sunmax.configure.vo.GraphChangeVo;import com.sunmax.configure.vo.GraphSourceChangeVo;import com.sunmax.configure.vo.GraphVariableChangeVo;import io.swagger.annotations.*;import org.springframework.web.bind.annotation.CrossOrigin;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.multipart.MultipartFile;import javax.annotation.Resource;import java.util.List;@RestController@CrossOrigin@RequestMapping("graph")@Api(tags = "图模管理控制层")public class GraphController {    @Resource    private GraphService graphService;    @Resource    private DeviceFeignService deviceFeignService;    @PostMapping("saveGraph")    @ApiOperation("新建或编辑图模数据")    @ApiOperationSupport(order = 1)    @ApiImplicitParam(name = "file", value = "图模文件", dataType = "File")    public ResponseResult<String> saveGraph(GraphChangeVo graphChangeVo, MultipartFile file) {        return graphService.saveGraph(graphChangeVo, file);    }    @PostMapping("deleteGraphByIds")    @ApiOperation("根据多个id删除数据")    @ApiImplicitParam(name = "ids", value = "多个id", dataType = "String", required = true)    @ApiOperationSupport(order = 2)    public ResponseResult<Void> deleteGraphByIds(String ids) {        return graphService.deleteGraphByIds(JSON.parseArray(ids, String.class));    }    @PostMapping("queryGraphList")    @ApiOperation("查询图模管理列表")    @ApiImplicitParam(name = "name", value = "名称(模糊查询)", dataType = "String")    @ApiOperationSupport(order = 3)    public ResponseResult<List<GraphListDto>> queryGraphList(String name) {        return graphService.queryGraphList(name);    }    @PostMapping("findGraphById")    @ApiOperation("根据图模id查询图模文件数据")    @ApiImplicitParam(name = "id", value = "图模id", dataType = "String", required = true)    @ApiOperationSupport(order = 4)    public ResponseResult<GraphDetailDto> findGraphById(String id) {        return graphService.findGraphById(id);    }    @PostMapping("relationDataSource")    @ApiOperation("图模关联数据源")    @ApiOperationSupport(order = 5)    public ResponseResult<Void> relationDataSource(GraphSourceChangeVo graphSourceChangeVo) {        return graphService.relationDataSource(graphSourceChangeVo);    }    @PostMapping("checkDataSource")    @ApiOperation("校验数据源是否调通")    @ApiImplicitParams({            @ApiImplicitParam(name = "dataSourceId", value = "数据源id", dataType = "String", required = true),            @ApiImplicitParam(name = "requestValue", value = "请求参数数据", dataType = "String", required = true)    })    @ApiOperationSupport(order = 6)    public ResponseResult<String> checkDataSource(String dataSourceId, String requestValue) {        return graphService.checkDataSource(dataSourceId, requestValue);    }    @PostMapping("findGraphSourceByGraphId")    @ApiOperation("根据图模id查询关联数据源数据")    @ApiImplicitParams({            @ApiImplicitParam(name = "graphId", value = "图模id", dataType = "String", required = true),            @ApiImplicitParam(name = "name", value = "名称(模糊搜索)", dataType = "String", required = true)    })    @ApiOperationSupport(order = 7)    public ResponseResult<List<GraphSourceDto>> findGraphSourceByGraphId(String graphId, String name) {        return graphService.findGraphSourceByGraphId(graphId, name);    }    @PostMapping("saveGraphVariable")    @ApiOperation("新增或编辑图模变量数据")    @ApiOperationSupport(order = 8)    public ResponseResult<Void> saveGraphVariable(GraphVariableChangeVo graphVariableChangeVo) {        return graphService.saveGraphVariable(graphVariableChangeVo);    }    @PostMapping("saveAllGraphVariable")    @ApiOperation("批量编辑图模变量数据")    @ApiOperationSupport(order = 9)    public ResponseResult<Void> saveAllGraphVariable(String graphVariableChangeVos) {        return graphService.saveAllGraphVariable(JSON.parseArray(graphVariableChangeVos, GraphVariableChangeVo.class));    }    @PostMapping("deleteGraphVariableByIds")    @ApiOperation("根据多个变量id批量删除图模变量数据")    @ApiImplicitParam(name = "ids", value = "多个变量id 例如['1','2']", dataType = "String", required = true)    @ApiOperationSupport(order = 10)    public ResponseResult<Void> deleteGraphVariableByIds(String ids) {        return graphService.deleteGraphVariableByIds(JSON.parseArray(ids, String.class));    }    @PostMapping("findGraphVariableByGraphId")    @ApiOperation("根据图模id查询关联变量数据")    @ApiImplicitParams({            @ApiImplicitParam(name = "graphId", value = "图模id", dataType = "String", required = true),            @ApiImplicitParam(name = "keyword", value = "关键词", dataType = "String", required = true)    })    @ApiOperationSupport(order = 11)    public ResponseResult<List<GraphVariableListDto>> findGraphVariableByGraphId(String graphId, String keyword) {        return graphService.findGraphVariableByGraphId(graphId, keyword);    }    @PostMapping("findGraphDataListByGraphId")    @ApiOperation("根据图模id查询图模接口数据")    @ApiOperationSupport(order = 12)    @ApiImplicitParams({            @ApiImplicitParam(name = "id", value = "数据id", dataType = "String", required = true),            @ApiImplicitParam(name = "type", value = "类型 1-图模id 2-域名id", dataType = "String", required = true)    })    public ResponseResult<GraphDataDto> findGraphDataListByGraphId(String id, Integer type) {        return graphService.findGraphDataListByGraphId(id, type);    }    @PostMapping("querySystemDeviceList")    @ApiOperation("查询系统设备列表")    @ApiOperationSupport(order = 13)    @ApiImplicitParams(@ApiImplicitParam(name = "siteId", value = "站点id", paramType = "query", required = true))    public ResponseResult<SystemDeviceListDto> querySystemDeviceList(String siteId) {        return deviceFeignService.querySystemDeviceList(siteId);    }    @PostMapping("findComputeNodeListByDeviceId")    @ApiOperation("根据站点/设备id查询计算节点列表")    @ApiOperationSupport(order = 14)    @ApiImplicitParam(name = "deviceId", value = "站点/设备唯一id", dataType = "String", required = true)    public ResponseResult<List<ComputeNodeListDto>> findComputeNodeListByDeviceId(String deviceId) {        return deviceFeignService.findComputeNodeListByDeviceId(deviceId);    }    @PostMapping("cloneGraph")    @ApiOperation("克隆图模")    @ApiOperationSupport(order = 15)    @ApiImplicitParams({            @ApiImplicitParam(name = "id", value = "图模id", dataType = "String", required = true),            @ApiImplicitParam(name = "userId", value = "用户id", dataType = "String", required = true),            @ApiImplicitParam(name = "file", value = "图模文件", dataType = "MultipartFile", required = true)    })    public ResponseResult<String> cloneGraph(String id, String userId, MultipartFile file) {        return graphService.cloneGraph(id, userId, file);    }    @PostMapping("findSiteListByUserId")    @ApiOperation("根据用户id查询站点列表")    @ApiOperationSupport(order = 16)    @ApiImplicitParam(name = "userId", value = "用户id", paramType = "query", required = true)    public ResponseResult<List<SiteListDto>> findSiteListByUserId(String userId) {        return deviceFeignService.findSiteListByUserId(userId);    }    @PostMapping("findFunctionListByDeviceId")    @ApiOperation("根据设备id获取功能点数据")    @ApiOperationSupport(order = 17)    @ApiImplicitParam(name = "deviceId", value = "设备id", paramType = "query", required = true)    public ResponseResult<List<FunctionListDto>> findFunctionListByDeviceId(String deviceId) {        return deviceFeignService.findFunctionListByDeviceId(deviceId);    }    @PostMapping("findSiteDeviceListBySiteId")    @ApiOperation("根据站点id查询站点的设备数据")    @ApiImplicitParam(name = "siteId", value = "站点id", dataType = "String", required = true)    @ApiOperationSupport(order = 18)    public ResponseResult<List<SiteDeviceTreeDto>> findSiteDeviceListBySiteId(String siteId) {        return deviceFeignService.findSiteDeviceListBySiteId(siteId);    }    @PostMapping("importGraph")    @ApiOperation("导入图模数据")    @ApiOperationSupport(order = 19)    @ApiImplicitParams({            @ApiImplicitParam(name = "userId", value = "用户id", dataType = "String", required = true),            @ApiImplicitParam(name = "file", value = "图模文件", dataType = "MultipartFile", required = true)    })    public ResponseResult<Void> importGraph(String userId, MultipartFile file) {        return graphService.importGraph(userId, file);    }}